#!/usr/bin/env bash
# generated by `kit setup` — do not edit; re-run kit setup
# kit v5 global git hook shim (__HOOK__): core.hooksPath points here for EVERY repo.
# Minimal Phase-3 version; Phase 4 (Task 4.4) adds repo-local hook chaining.
# Fail-loud (design §7.5): no config / no kit_root / no guard script → block.
CFG="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." 2>/dev/null && pwd)/config.toml"
KIT_ROOT="$(sed -nE '/^[[:space:]]*\[/q; s/^[[:space:]]*kit_root[[:space:]]*=[[:space:]]*"([^"]*)".*/\1/p' "$CFG" 2>/dev/null | head -n 1)"
GUARD="$KIT_ROOT/plugin/guard/__HOOK__.sh"
if [[ -z "$KIT_ROOT" || ! -f "$GUARD" ]]; then
    echo "KIT GUARD: not configured (config: $CFG, guard: ${GUARD}) — run: kit setup" >&2
    exit 1
fi
exec bash "$GUARD" "$@"
